'use client';

import { useState, useEffect } from 'react';
import { firestore } from '@/lib/firebase';
import { collection, onSnapshot, QuerySnapshot, DocumentData, doc, deleteDoc } from 'firebase/firestore';
import Link from 'next/link';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  subCategory: string;
  isAvailable: boolean;
}

export default function ProductsPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const collectionRef = collection(firestore, 'products');

    const unsubscribe = onSnapshot(collectionRef,
      (snapshot: QuerySnapshot<DocumentData>) => {
        const productsData = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        })) as Product[];

        // TAMBAHKAN BARIS INI UNTUK MENGINTEROGASI DATA
        // console.log("ISI DATA MENTAH DARI FIREBASE:", productsData);

        setProducts(productsData);
        setLoading(false);
      },
      (err) => {
        console.error("Error fetching products: ", err);
        setError("Gagal memuat data produk. Silakan coba lagi.");
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

 const handleDelete = async (productId: string) => {
    // Minta konfirmasi sebelum menghapus
    if (window.confirm("Apakah kamu yakin ingin menghapus produk ini?")) {
      try {
        const docRef = doc(firestore, 'products', productId);
        await deleteDoc(docRef);
        alert('Produk berhasil dihapus!');
      } catch (error) {
        console.error("Error removing document: ", error);
        alert('Gagal menghapus produk.');
      }
    }
  };
  
  if (loading) {
    return <div className="text-center mt-10">Memuat produk...</div>;
  }

  if (error) {
    return <div className="text-center mt-10 text-red-500">{error}</div>;
  }

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Manajemen Produk</h1>
        <Link href="/products/new">
            <button className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700">
            + Tambah Produk Baru
            </button>
        </Link>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-md">
        <table className="w-full text-left">
          <thead>
            <tr className="border-b">
              <th className="p-4">Nama Produk</th>
              <th className="p-4">Kategori</th>
              <th className="p-4">Harga</th>
              <th className="p-4">Status</th>
              <th className="p-4">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {products.length === 0 ? (
              <tr>
                <td colSpan={5} className="text-center p-6 text-gray-500">
                  Belum ada produk. Silakan tambahkan produk baru.
                </td>
              </tr>
            ) : (
              products.map((product) => (
                <tr key={product.id} className="border-b hover:bg-gray-50">
                  <td className="p-4 font-medium">{product.name}</td>
                  <td className="p-4 text-gray-600">{product.subCategory}</td>
                  <td className="p-4 text-gray-600">
                    Rp {product.price?.toLocaleString('id-ID')|| 'N/A'}
                  </td>
                  <td className="p-4">
                    <span className={`px-2 py-1 text-xs rounded-full ${
                      product.isAvailable
                        ? 'bg-green-100 text-green-800'
                        : 'bg-red-100 text-red-800'
                    }`}>
                      {product.isAvailable ? 'Tersedia' : 'Habis'}
                    </span>
                  </td>
                  <td className="p-4 space-x-2">
                    <Link href={`/products/edit/${product.id}`}>
                        <button className="text-blue-600 hover:underline">Edit</button>
                    </Link>
                    <button 
                        onClick={() => handleDelete(product.id)}
                        className="text-red-600 hover:underline"
                        >
                            Delete
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}